arguments.command:
python3 -c "
import json
for f in ['rollouts/1.jsonl','rollouts/60.jsonl']:
    print('=====', f)
    with open(f) as fh:
        for i,line in enumerate(fh):
            line=line.strip()
            if not line: continue
            d=json.loads(line)
            if i==0:
                print('keys:', list(d.keys()))
                for k in d:
                    v=d[k]
                    if isinstance(v,str) and len(v)>100:
                        print(' ',k,'=',repr(v[:150]))
                    else:
                        print(' ',k,'=',v)
                print('---')
            if i>=3: break
"

